class Solution {
public:
    int similarPairs(vector<string>& words) {
        unordered_map<int,int> freq;
        for (const string& w : words) {
            int mask = 0;
            for (char c : w) {
                mask |= (1 << (c - 'a'));
            }
            freq[mask]++;
        }
        int ans = 0;
        for (auto& p : freq) {
            int c = p.second;
            ans += c * (c - 1) / 2;
        }
        return ans;
    }
};
